import { View, div, svg } from "gpui-kit";
import { h_flex } from "gpui-base";
import { spaces, agents, theme, run, window, keys, exec, home, notify, updates, shared, setShared } from "herdr";
// <flat-tokens> generated by lib/herdr_flat/sync from lib/herdr_flat/flat.js; edit there
const R = 1;
const LINE = 1;
const UNIT = 5;
const S1 = UNIT;
const S2 = UNIT * 2;
const S3 = UNIT * 3;
const S4 = UNIT * 4;
const HAIR = 2;
const TEXT = 13;
const SMALL = 11;
const H3 = 15;
const H2 = 18;
const H1 = 22;
// </flat-tokens>

// Herdr never updates clones, so after a Herdr update the flat mods lag
// upstream until someone ports the changes. On start this compares the
// running version with the one these mods were cloned from; when they differ
// it posts a toast once per version and keeps a status bar item until the
// port lands. Both open a Claude tab in the dotfiles repo with the porting
// task (docs/herdr-flat.md, "Porting a Herdr update").
const SELF = "/.config/herdr-app/mods/flat-workspace-status/mod.json";

async function portNeeded() {
  const now = updates().app.version;
  const file = home() + SELF;
  const json = await exec("cat", [file]);
  const base = json.code === 0 ? JSON.parse(json.stdout).cloned_from?.version : null;
  if (!base || !now || base === now) return null;
  // The mod's files are symlinks into the repo: follow one back to its root.
  const real = await exec("readlink", ["-f", file]);
  const repo = real.stdout.trim().replace(/\/global\/\.config\/herdr-app\/mods\/.*$/, "");
  return { base, now, repo };
}

function portTab(p) {
  return {
    name: "port flat mods",
    folder: p.repo,
    argv: ["claude"],
    task: `Herdr app updated from ${p.base} to ${p.now}. Port the upstream changes into the flat layout: follow "Porting a Herdr update" in docs/herdr-flat.md.`,
  };
}

export default class WorkspaceStatus extends View {
  init(_props, cx) {
    cx.spawn(async (cx) => {
      const p = await portNeeded().catch(() => null);
      if (!p) return;
      this.port = p;
      cx.notify();
      if (shared("flat.port-announced") === p.now) return;
      setShared("flat.port-announced", p.now);
      notify({
        title: `Herdr ${p.now}: flat mods need a port`,
        body: `Cloned from ${p.base}. Click to port.`,
        level: "info",
        timeout: 20000,
        action: { name: "tab.new", args: portTab(p) },
      });
    });
  }

  // The palette key as actually bound, not a hardcoded one; without a
  // binding the hint stays useful ("commands") instead of lying.
  hint(t) {
    const mac = window()?.platform === "macos";
    const mod = { cmd: mac ? "⌘" : "Ctrl+", ctrl: mac ? "⌃" : "Ctrl+", shift: mac ? "⇧" : "Shift+", alt: mac ? "⌥" : "Alt+", option: mac ? "⌥" : "Alt+" };
    const b = keys().find((k) => k.section === "global" && k.action === "app.palette");
    const parts = b && b.keys.endsWith("--") ? [...b.keys.slice(0, -2).split("-"), "-"] : b?.keys.split("-");
    const key = parts && parts.map((p) => mod[p.toLowerCase()] ?? p.toUpperCase()).join("");
    return key ? `${key}  commands` : "commands";
  }

  render() {
    const t = theme();
    const space = spaces().find(s => s.active);
    const list = agents();
    const needs = list.filter(a => a.status === "blocked").length;
    const label = (icon, text) => h_flex().gap(S1).items_center().child(svg(`mods/workspace-chrome/${icon}.svg`).size(13)).child(text);
    return h_flex().size_full().px(S3).gap(S3).items_center().bg(t.chrome).border_t(LINE).border_color(t.border).text_size(SMALL).text_color(t.muted)
      .child(label(space?.machine ? "server" : "monitor", space?.machine ?? "This computer"))
      .when(Boolean(space?.branch), el => el.child(label("branch", space.branch)))
      .child(h_flex().gap(S1).items_center().child(div().size(6).rounded_full().bg(t.dim)).child(`${list.length} agents`)
        .when(needs > 0, el => el.child(div().text_color(t.blocked).child(`· ${needs} needs you`))))
      .child(div().flex_1())
      .when(Boolean(this.port), el => el.child(div().id("flat-port").cursor_pointer().text_color(t.accent).hover(s => s.text_color(t.foreground))
        .on_click(() => run("tab.new", portTab(this.port)))
        .child(`port flat mods ${this.port.base} \u2192 ${this.port.now}`)))
      .child(div().id("palette").text_color(t.dim).on_click(() => run("mod.open", { name: "flat-palette" })).child(this.hint(t)));
  }
}
